// Gallery Generator configuration
// Pattern to ensure perfect packing in a 3-column grid (grid-flow-dense)
// Total spans must align to prevent gaps.
// Large=2x2 (4 cells), Small=1x1 (1 cell), Wide=2x1 (2 cells), Tall=1x2 (2 cells)
// Pattern of 10:
// 1. Large (4)
// 2. Small (1)
// 3. Small (1) 
// 4. Tall (2)
// 5. Wide (2)
// 6. Small (1)
// 7. Small (1)
// 8. Small (1)
// 9. Small (1)
// 10. Tall (2) 
// Total area = 4+1+1+2+2+1+1+1+1+2 = 16 (Not divisible by 3) -> 16%3 = 1
// Let's adjust to be divisible by 3 (columns) for a full block.
// Try Area 15 (15 cells / 3 cols = 5 rows)
// 1. Large (4)
// 2. Small (1)
// 3. Small (1) -> Row 1 & 2 full (2+1, 2+1)
// 4. Tall (2)
// 5. Wide (2)
// 6. Small (1)
// 7. Small (1) -> Row 3 & 4 (1+2, 2+1)
// 8. Small (1)
// 9. Small (1)
// 10. Small (1) -> Row 5 (1+1+1)
// Total Items: 10. Total Area: 4+1+1+2+2+1+1+1+1+1 = 15.
const SIZES: { size: 'small' | 'wide' | 'tall' | 'large', w: number, h: number }[] = [
  { size: 'large', w: 800, h: 800 }, // 2x2 (4)
  { size: 'small', w: 400, h: 400 }, // 1x1 (1)
  { size: 'small', w: 400, h: 400 }, // 1x1 (1)
  { size: 'tall', w: 400, h: 800 },  // 1x2 (2)
  { size: 'wide', w: 800, h: 400 },  // 2x1 (2)
  { size: 'small', w: 400, h: 400 }, // 1x1 (1)
  { size: 'small', w: 400, h: 400 }, // 1x1 (1)
  { size: 'small', w: 400, h: 400 }, // 1x1 (1)
  { size: 'small', w: 400, h: 400 }, // 1x1 (1)
  { size: 'small', w: 400, h: 400 }, // 1x1 (1)
];

// Generate 40 items (4 pages of 10)
export const GALLERY_ITEMS: GalleryItem[] = Array.from({ length: 40 }).map((_, i) => {
  const patternIndex = i % 10;
  const config = SIZES[patternIndex];
  
  return {
    id: `g-${i}`,
    url: `https://picsum.photos/${config.w}/${config.h}?random=${i + 20}`,
    title: `Memory #${i + 1}`,
    description: 'Captured moment in time.',
    size: config.size,
    width: config.w,
    height: config.h
  };
});